package com.roughpath.alpha;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.java_websocket.client.WebSocketClient;import org.java_websocket.handshake.ServerHandshake;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class PriceMonitorService extends Service {
 private volatile WebSocketClient socket,primaryProbe;private volatile long lastPrimaryProbe=0;private static final String PRICE_URL="wss://backend-pricing.eu.gains.trade/v4";private final ScheduledExecutorService jobs=Executors.newScheduledThreadPool(2);private PowerManager.WakeLock wake;private volatile boolean stopped=false;private volatile long lastFrame=0,lastConnect=0;private volatile boolean historyBusy=false;
 public void onCreate(){super.onCreate();MarketStore.init(this);NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("prices","Background market monitoring",NotificationManager.IMPORTANCE_LOW));Intent launch=new Intent(this,MainActivity.class);PendingIntent open=PendingIntent.getActivity(this,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent stop=new Intent(this,PriceMonitorService.class).setAction("STOP");PendingIntent stopAction=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"prices").setContentTitle("RoughPath is monitoring markets").setContentText("Candles and paper positions continue in the background").setSmallIcon(android.R.drawable.ic_menu_recent_history).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Stop monitoring",stopAction).build()).build();try{if(Build.VERSION.SDK_INT>=34)startForeground(42,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(42,n);}catch(RuntimeException e){MarketStore.running=false;MarketStore.status="Background monitor unavailable · foreground prices active";android.util.Log.w("RoughPath","Foreground registration rejected",e);stopSelf();return;}MarketStore.running=true;wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"RoughPath:Prices");try{wake.acquire();}catch(SecurityException e){android.util.Log.w("RoughPath","Wake lock unavailable",e);}jobs.scheduleWithFixedDelay(()->{if(stopped)return;try{long now=System.currentTimeMillis();if(socket!=null&&socket.isOpen()&&!socket.getURI().getHost().equals(URI.create(GainsEndpoints.primary(PRICE_URL)).getHost())&&now-lastPrimaryProbe>60000)probePrimary();if(socket==null||socket.isClosed()||(now-lastFrame>20000&&now-lastConnect>20000)){connect();}}catch(Exception e){MarketStore.status="Reconnecting";}},0,3,TimeUnit.SECONDS);jobs.scheduleWithFixedDelay(this::history,0,60,TimeUnit.SECONDS);jobs.scheduleWithFixedDelay(this::recoverHttpPrice,2,30,TimeUnit.SECONDS);}
 private synchronized void connect(){if(stopped)return;lastConnect=System.currentTimeMillis();if(socket!=null){WebSocketClient old=socket;socket=null;if(System.currentTimeMillis()-lastFrame>20000)GainsEndpoints.failure(old.getURI().toString(),System.currentTimeMillis());old.close();}MarketStore.status="Connecting";NetworkTrace.log(GainsEndpoints.candidates(PRICE_URL,System.currentTimeMillis())[0],"connecting","Native WebSocket attempt");try{socket=new WebSocketClient(new URI(GainsEndpoints.candidates(PRICE_URL,System.currentTimeMillis())[0])){public void onOpen(ServerHandshake h){if(PriceMonitorService.this.socket!=this||stopped)return;lastFrame=System.currentTimeMillis();MarketStore.status="Socket open · awaiting price frame";NetworkTrace.log(getURI().toString(),"waiting","Handshake open");jobs.execute(()->recoverHttpPrice());}public void onMessage(String raw){if(PriceMonitorService.this.socket!=this||stopped)return;long now=System.currentTimeMillis();if(PriceFeed.ingest(raw,now)>0){lastFrame=now;GainsEndpoints.success(getURI().toString());MarketStore.status="Connected · "+getURI().getHost();NetworkTrace.log(getURI().toString(),"healthy","Fresh v4 oracle prices");}else NetworkTrace.log(getURI().toString(),"rejected",MarketStore.feedError.isEmpty()?"No supported prices in frame":MarketStore.feedError);}public void onClose(int code,String reason,boolean remote){if(PriceMonitorService.this.socket!=this||stopped)return;GainsEndpoints.failure(getURI().toString(),System.currentTimeMillis());MarketStore.status="Disconnected · switching endpoint";NetworkTrace.log(getURI().toString(),"closed","Code "+code+" "+reason);}public void onError(Exception ex){if(PriceMonitorService.this.socket!=this||stopped)return;GainsEndpoints.failure(getURI().toString(),System.currentTimeMillis());MarketStore.status="Price socket error · switching endpoint";NetworkTrace.log(getURI().toString(),"error",ex.getClass().getSimpleName()+": "+ex.getMessage());close();}};socket.setConnectionLostTimeout(15);socket.connect();}catch(Exception e){MarketStore.status="Connection failed · retrying";}}
 private static long snapshotTime(JSONObject r){long t=r.optLong("time",0);if(t>0&&t<1000000000000L)t*=1000;long now=System.currentTimeMillis();return t>now+2000?0:Math.min(t,now);}
 private volatile String priceHttpEndpoint=GainsEndpoints.primary("https://backend-pricing.eu.gains.trade/charts");
 private void recoverHttpPrice(){if(stopped)return;try{JSONObject j=getJson(priceHttpEndpoint);long stamp=snapshotTime(j),now=System.currentTimeMillis();if(stamp<=0||now-stamp>120000)return;JSONArray os=j.getJSONArray("opens"),hs=j.getJSONArray("highs"),ls=j.getJSONArray("lows"),cs=j.getJSONArray("closes");for(int id=0;id<Math.min(Math.min(os.length(),hs.length()),Math.min(ls.length(),cs.length()))&&id<=1000;id++)MarketStore.seedOhlc(id,os.optDouble(id),hs.optDouble(id),ls.optDouble(id),cs.optDouble(id),stamp);NetworkTrace.log(priceHttpEndpoint,"healthy","Chart candles seeded; execution waits for live oracle");}catch(Exception e){NetworkTrace.log(priceHttpEndpoint,"error",e.getClass().getSimpleName()+": "+e.getMessage());}}
 private synchronized void probePrimary(){if(stopped||primaryProbe!=null)return;lastPrimaryProbe=System.currentTimeMillis();try{final WebSocketClient p=new WebSocketClient(new URI(GainsEndpoints.primary(PRICE_URL))){public void onOpen(ServerHandshake h){}public void onMessage(String raw){synchronized(PriceMonitorService.this){if(stopped||(primaryProbe!=this&&socket!=this))return;long now=System.currentTimeMillis();if(PriceFeed.ingest(raw,now)<=0)return;if(socket==this){lastFrame=now;return;}WebSocketClient old=socket;socket=this;primaryProbe=null;lastFrame=now;GainsEndpoints.success(getURI().toString());MarketStore.status="Connected · primary recovered";if(old!=null)old.close();}}public void onClose(int code,String reason,boolean remote){synchronized(PriceMonitorService.this){if(primaryProbe==this)primaryProbe=null;else if(socket==this&&!stopped)GainsEndpoints.failure(getURI().toString(),System.currentTimeMillis());}}public void onError(Exception e){close();}};primaryProbe=p;p.setConnectionLostTimeout(15);p.connect();jobs.schedule(()->{if(primaryProbe==p){primaryProbe=null;p.close();}},10,TimeUnit.SECONDS);}catch(Exception e){primaryProbe=null;}}
 private JSONObject getJson(String url)throws Exception{Exception error=null;for(String candidate:GainsEndpoints.candidates(url,System.currentTimeMillis()))try{if(url.endsWith("/charts"))priceHttpEndpoint=candidate;NetworkTrace.log(candidate,"connecting","Native HTTPS");JSONObject j=getJsonOnce(candidate);NetworkTrace.log(candidate,"healthy","Read completed");GainsEndpoints.success(candidate);return j;}catch(Exception e){error=e;NetworkTrace.log(candidate,"error",e.getClass().getSimpleName()+": "+e.getMessage());GainsEndpoints.failure(candidate,System.currentTimeMillis());}throw error;}
 private JSONObject getJsonOnce(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setUseCaches(false);c.setRequestProperty("Cache-Control","no-cache");c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>16000000)throw new IOException("Response too large");}}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();}}
 private void history(){synchronized(this){if(historyBusy||stopped)return;historyBusy=true;}boolean ok=false;try{boolean active=false;for(int p:new int[]{0,1,300,313})if(MarketStore.hasHistoryPosition(p))active=true;if(!active){MarketStore.historyStatus="No positions · backfill paused";return;}
  int[] pairs={0,1,300,313};String[] symbols={"BTC-USD","ETH-USD","BTCDEGEN-USD","ETHDEGEN-USD"};
  for(int i=0;i<pairs.length&&!stopped;i++){if(!MarketStore.hasHistoryPosition(pairs[i]))continue;for(String chain:new String[]{"arbitrum","polygon"}){if(!MarketStore.hasHistoryPosition(pairs[i]))break;try{long to=System.currentTimeMillis(),from=to-300*60000L;JSONArray rows=getJson("https://api.gains.trade/v1/"+chain+"/markets/"+symbols[i]+"/candles?interval=1m&from="+from+"&to="+to).getJSONArray("data"),a=new JSONArray();for(int k=0;k<rows.length();k++){JSONObject r=rows.getJSONObject(k);double o=r.getDouble("open"),h=r.getDouble("high"),l=r.getDouble("low"),close=r.getDouble("close");long t=r.getLong("time");if(t>=1000000000L&&t<1000000000000L)t*=1000;t=t/60000*60000;if(t>0&&t<=to&&Double.isFinite(o)&&Double.isFinite(h)&&Double.isFinite(l)&&Double.isFinite(close)&&l>0&&h>=Math.max(o,close)&&l<=Math.min(o,close))a.put(new JSONObject().put("t",t).put("o",o).put("h",h).put("l",l).put("c",close).put("source","gains-history"));}MarketStore.merge(pairs[i],a);MarketStore.save(true);ok=true;break;}catch(Exception ignored){}}}
  MarketStore.historyStatus=ok?"Gains history + live · 1m":"History unavailable · cached/live candles shown";
 }finally{historyBusy=false;/* The fixed-delay job already retries every minute; never fork retry chains. */}}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){getSharedPreferences("market",0).edit().putBoolean("keepAlive",false).apply();stopSelf();return START_NOT_STICKY;}if(i!=null&&"RECONNECT".equals(i.getAction()))try{jobs.execute(()->{if(System.currentTimeMillis()-lastConnect>1000||socket==null||socket.isClosed())connect();});}catch(RejectedExecutionException ignored){}return START_STICKY;}
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){stopped=true;MarketStore.running=false;MarketStore.status="Monitoring stopped";if(socket!=null)socket.close();if(primaryProbe!=null)primaryProbe.close();jobs.shutdownNow();MarketStore.save(true);if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
